# handling Application Server side of iperf
import six
from ...exceptions import UeProcedureError, DataTransferMissingArguments
from moler.device.unixremote import UnixRemote
from moler.device.unixremote2 import UnixRemote2
from moler.io.raw.sshshell import ThreadedSshShell
from . import host
from .endpoint import IperfEndpoint


class AppSvrEndpoint(IperfEndpoint):
    """Managing Application Server side of iperf data transfer."""
    def __init__(self, name, dt_definition, configuration, cmd_options, logger):
        """
        Basic initialization.

        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: configuration
        :param cmd_options: CmdOptions instance
        :param logger: logger to use
        """
        configuration = self._update_app_servers_configuration(configuration, dt_definition.protocol_details)
        super().__init__(name=name, dt_definition=dt_definition,
                                             configuration=configuration, cmd_options=cmd_options)
        self._validate_app_servers_config()
        iperf_host = self.select_app_server_to_use()
        self.host_device = host.get_device(device_def=iperf_host,
                                           data_traffic_name=self._name,
                                           endpoint_name='APP_SVR', logger=logger)

    @staticmethod
    def _update_app_servers_configuration(configuration, protocol_details):
        configuration = AppSvrEndpoint._convert_app_servers_config_2internal_format(configuration)
        # app server given in test as dict
        if 'app_server' in protocol_details:
            app_server_def = protocol_details['app_server']
            if isinstance(app_server_def, dict):  # either string or dict
                configuration['APP_SERVERS'] = {'APPSERVER0': app_server_def}
                configuration['app_server'] = 'APPSERVER0'
        elif 'app_server_index' in protocol_details:
            available_appservers = configuration['APP_SERVERS']
            app_server_index = int(protocol_details['app_server_index'])
            expected_name = f"APPSERVER{app_server_index}"
            if expected_name in available_appservers:
                configuration['app_server'] = expected_name
                configuration['app_server_index'] = app_server_index
        return configuration

    @staticmethod
    def _convert_app_servers_config_2internal_format(configuration):
        if 'APP_SERVERS' in configuration:
            # APP_SERVERS may be given as dict (internal format) or list (new config format)
            available_appservers = configuration['APP_SERVERS']
            if isinstance(available_appservers, list):
                app_servers_internal = {}
                app_servers_order = []
                for idx, app_svr_ep in enumerate(available_appservers):
                    generated_appsvr_name = f"APPSERVER{idx}"
                    app_servers_internal[generated_appsvr_name] = app_svr_ep
                    app_servers_order.append(app_svr_ep)

                configuration['APP_SERVERS'] = app_servers_internal
                configuration['app_servers_order'] = app_servers_order  # existence of this key indicates new format

        configuration = AppSvrEndpoint._select_default_app_server(configuration)
        return configuration

    @staticmethod
    def _select_default_app_server(configuration):
        if ('APP_SERVERS' in configuration) and ('default_app_server_index' in configuration):
            available_appservers = configuration['APP_SERVERS']
            default_app_server_index = int(configuration['default_app_server_index'])
            expected_name = f"APPSERVER{default_app_server_index}"
            if expected_name in available_appservers:
                configuration['app_server'] = expected_name
                configuration['app_server_index'] = default_app_server_index

        return configuration

    def _validate_app_servers_config(self):
        err_msg = ''
        if 'APP_SERVERS' not in self._configuration:
            err_msg += "\n missing APP_SERVERS key"
        else:
            for app_svr_name in self._configuration['APP_SERVERS']:
                app_svr_def = self._configuration['APP_SERVERS'][app_svr_name]
                err_msg += self._validate_app_servers_keys(app_svr_name=app_svr_name, app_svr_def=app_svr_def)

        if err_msg:
            example = {
                'APP_SERVERS': {'APPSERVER0': {'host': 'APPSERVER_0', 'bind_interface_ip': '192.168.1.2'},
                                'APPSERVER1': {'host': 'APPSERVER_1',
                                               'bind_interface_ip': '192.168.1.3',
                                               'iperf': {'path': '/usr/local/bin/', 'use_sudo_when': "port<1200"}}},
                'app_server': 'APPSERVER0',
            }
            msg = f"expected cfg like: 'data_transfer': {example}; got: 'data_transfer': {self._configuration}{err_msg}"
            raise UeProcedureError(msg)

    @staticmethod
    def _validate_app_servers_keys(app_svr_name, app_svr_def):
        err_msg = ''
        allowed_app_server_keys = ['host', 'bind_interface_ip', 'iperf']
        if 'host' not in app_svr_def:  # the only required key
            err_msg += f"\n missing 'host' key of configuration['APP_SERVERS']['{app_svr_name}']"
        for key in app_svr_def:
            if key not in allowed_app_server_keys:
                err_msg += f"\n unknown app_server key '{key}' - allowed: {allowed_app_server_keys}"
            err_msg += AppSvrEndpoint._validate_app_servers_iperf_keys(key, app_svr_def=app_svr_def)
        return err_msg

    @staticmethod
    def _validate_app_servers_iperf_keys(key, app_svr_def):
        err_msg = ''
        allowed_app_server_iperf_keys = ['path', 'use_sudo_when', 'port']
        if key == 'iperf':
            for subkey in app_svr_def['iperf']:
                if subkey not in allowed_app_server_iperf_keys:
                    err_msg += "\n unknown {} key '{}' - allowed: {}".format("app_server/iperf",
                                                                             subkey,
                                                                             allowed_app_server_iperf_keys)
        return err_msg

    def select_app_server_to_use(self):
        """Select application server to use for iperf"""
        # start from ip expected to be iperf server endpoint
        endpoint_name = self.appsvr_endpoint_name
        app_svr_ep = self._configuration['APP_SERVERS'][endpoint_name]
        app_svr = app_svr_ep['host']
        return app_svr

    @property
    def appsvr_endpoint_name(self):
        """Name of APP-SVR endpoint to be used for selecting AppServer of iperf"""
        # return self.appsvr_endpoint.endpoint_name
        known_endpoints = list(self._configuration['APP_SERVERS'].keys())
        protocol_details = self._dt_definition.protocol_details
        # 1) the one selected in test
        if ('app_server' in protocol_details) and isinstance(protocol_details['app_server'], six.string_types):
            endpoint_name = protocol_details['app_server']
        # 2) the one selected inside iperf configuration
        elif 'app_server' in self._configuration:
            endpoint_name = self._configuration['app_server']
        # 3) the only one known to 'APP_SERVERS'
        elif len(known_endpoints) == 1:
            endpoint_name = known_endpoints[0]
        else:
            msg = "No app_server selected to use for iperf"
            raise UeProcedureError(f"{msg}; available: {known_endpoints}")

        if endpoint_name not in known_endpoints:
            msg = f"Selected app_server=={endpoint_name} doesn't exist"
            raise UeProcedureError(f"{msg}; available: {known_endpoints}")

        return endpoint_name

    @property
    def iperf_path(self):
        """Return path to iperf at APP-SVR side"""
        try:
            endpoint_name = self.appsvr_endpoint_name
            app_svr_ep = self._configuration['APP_SERVERS'][endpoint_name]
            path = app_svr_ep['iperf']['path']
        except KeyError:
            path = None
        return path

    @property
    def iperf_port(self):
        """Return port to use by iperf at APP-SVR side"""
        protocol_details = self._dt_definition.protocol_details
        port = 5001 if self.config_version >= 2.0 else None
        if 'port' in protocol_details:
            port = protocol_details['port']
        elif self.config_version >= 2.0:
            try:
                endpoint_name = self.appsvr_endpoint_name
                app_svr_ep = self._configuration['APP_SERVERS'][endpoint_name]
                port = app_svr_ep['iperf']['port']
            except KeyError:
                pass
        if port is not None:
            port = int(port)
        return port

    @property
    def endpoint_ip(self):
        """IP of Application Server"""
        endpoint_name = self.appsvr_endpoint_name
        app_svr_ep = self._configuration['APP_SERVERS'][endpoint_name]
        ip = None
        if 'bind_interface_ip' in app_svr_ep:
            ip = app_svr_ep['bind_interface_ip']
        else:  # no interface specified, use the one used to ssh into machine
            if isinstance(self.host_device.io_connection, ThreadedSshShell):
                ip = self.host_device.io_connection.sshshell.host
            elif isinstance(self.host_device, UnixRemote) or isinstance(self.host_device, UnixRemote2):
                ip = self._remote_ip(self.host_device._configurations['CONNECTION_HOPS'])
            elif self.host_device.__class__.__name__ == 'UnixLocal':
                ip = '127.0.0.1'
        if ip is None:
            raise DataTransferMissingArguments(f"Can't find IP of {endpoint_name}")
        return ip

    @property
    def host_bind_interface_ip(self):
        """Return IP of AppServer interface intended to bind to"""
        # as default we bind to endpoint_ip of host
        # but derived classes may have different endpoint_ip and AppSvr-bindingIP
        return self.endpoint_ip

    def seen_ip_of_other_endpoint(self, other_endpoint_ip):
        """IP of UE host as seen by AppSvr"""
        # default is 1:1 IP as taken from  ue_host.endpoint_ip
        # but derived classes may change it
        # f.ex. if they use NAT proxy
        return other_endpoint_ip

    @staticmethod
    def _remote_ip(connection_hops):
        for from_state in connection_hops:
            for to_state in connection_hops[from_state]:
                if to_state == 'UNIX_REMOTE':
                    ip = connection_hops[from_state][to_state]['command_params']['host']
                    return ip
        return None

    @property
    def need_root(self):
        """Return True if iperf needs to be run inside shell of root user"""
        try:
            need_root = self._configuration['iperf']['need_root']
        except KeyError:
            need_root = False
        return need_root

    @property
    def device_target_state(self):
        """Target state of moler device required to run iperf from (APP-SVR side)"""
        if self.host_device.__class__.__name__ == 'UnixLocal':
            return 'UNIX_LOCAL_ROOT' if self.need_root else 'UNIX_LOCAL'
        return 'UNIX_REMOTE'

    @property
    def sudo_password(self):
        """Password required when iperf needs to start via sudo at APP-SVR side"""
        password = ''
        iperf_host = self.select_app_server_to_use()
        if isinstance(iperf_host, dict):
            password = iperf_host.get('password', '')
        elif hasattr(self, 'host_device'):
            # take it from ssh command or ssh io
            password = host.find_ssh_passwd(host_device=self.host_device)
        return password

    @property
    def need_sudo(self):
        """Return True if running iperf requires sudo"""
        sudo_port = 1024  # default, accessing ports below 1024 requires root
        try:
            sudo_rule = self._configuration['iperf']['use_sudo_when']
            if sudo_rule.startswith('port<'):
                _, _, sudo_port = sudo_rule.partition("<")
                sudo_port = int(sudo_port)
        except KeyError:
            pass

        port = self.iperf_port if self.config_version >= 2.0 else self._cmd_options.port
        return port < sudo_port

    def client_options(self, ue_ip, ue_iperf_port=None):
        """
        Generate options for iperf client command

        :param ue_ip: AppSvrEndpoint has no knowledge about IP of other end (UE), it must be provided.
        :param ue_iperf_port: same as above
        :return: iperf options string
        """
        server_ip = self.seen_ip_of_other_endpoint(ue_ip)
        client_ip = self.host_bind_interface_ip
        # inside iperf client options:
        # - client_ip is used for binding to IP at client side
        # - server_ip is used for:
        #   - defining where iperf client should connect to
        #   - detecting if IPv6 should be used at server side
        return self._cmd_options.client_options(client_ip, server_ip, port=ue_iperf_port)

    def server_options(self, ue_ip):
        """
        Generate options for iperf server command

        :param ue_ip: AppSvrEndpoint has no knowledge about IP of other end (UE), it must be provided.
        :return: iperf options string
        """
        server_ip = self.host_bind_interface_ip
        client_ip = self.seen_ip_of_other_endpoint(ue_ip)
        # inside iperf server options:
        # - server_ip is used for binding to IP at server side
        # - client_ip is used for detecting if IPv6 should be used at server side
        return self._cmd_options.server_options(client_ip, server_ip, port=self.iperf_port)

    def get_client_command_object(self, ue_ip, ue_iperf_port=None):
        """Return moler Command object for iperf client"""
        iperf_client_options = self.client_options(ue_ip, ue_iperf_port)
        iperf_client_cmd = self._get_iperf_command_object(iperf_options=iperf_client_options)
        return iperf_client_cmd

    def get_server_command_object(self, ue_ip):
        """Return moler Command object for iperf server"""
        iperf_server_options = self.server_options(ue_ip)
        iperf_server_cmd = self._get_iperf_command_object(iperf_options=iperf_server_options)
        return iperf_server_cmd

    def _get_iperf_command_object(self, iperf_options):
        iperf_cmd = host.get_iperf_command_object(host_device=self.host_device,
                                                  iperf_options=iperf_options,
                                                  iperf_path=self.iperf_path,
                                                  need_sudo=self.need_sudo,
                                                  sudo_password=self.sudo_password)
        return iperf_cmd

    def prepare_host_device(self):
        """Change host device state to expected target state"""
        self.host_device.goto_state(state=self.device_target_state)
